import{_ as a,o as n,c as t,a2 as c}from"./chunks/framework.DX07gj3j.js";const k=JSON.parse('{"title":"Architecture","description":"Understand the packages and data flow behind a WreckCheck scan.","frontmatter":{"title":"Architecture","description":"Understand the packages and data flow behind a WreckCheck scan."},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1786705916000}'),s={name:"architecture.md"};function r(i,e,o,d,p,l){return n(),t("div",null,[...e[0]||(e[0]=[c(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>WreckCheck is a pnpm workspace built around a small, reusable scan core. The published <code>wreckcheck</code> CLI composes the internal packages; checks and reporters can also be used directly by integrations inside the workspace.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>@wreckcheck/core</code></td><td>Project discovery, scanning orchestration, config and policy, scoring, IDs, fingerprints, and verification adapters.</td></tr><tr><td><code>@wreckcheck/checks</code></td><td>Secrets, environment, dependencies, Docker, build, and verification checks.</td></tr><tr><td><code>@wreckcheck/reporter</code></td><td>Terminal, JSON, SARIF, and GitHub job-summary renderers.</td></tr><tr><td><code>wreckcheck</code></td><td>The public command-line interface.</td></tr><tr><td><code>@wreckcheck/action</code></td><td>GitHub Action wrapper that writes summaries, annotations, SARIF, and job status.</td></tr></tbody></table><h2 id="scan-flow" tabindex="-1">Scan flow <a class="header-anchor" href="#scan-flow" aria-label="Permalink to &quot;Scan flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CLI or GitHub Action</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         ├── loadConfig() ──► policy: failOn + ignored IDs</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         └── scan(rootDir, checks)</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    ├── discoverProject()</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    └── run checks concurrently</span></span>
<span class="line"><span>                            │</span></span>
<span class="line"><span>                            ▼</span></span>
<span class="line"><span>                    ScanResult</span></span>
<span class="line"><span>                       ├── findings</span></span>
<span class="line"><span>                       ├── verification results</span></span>
<span class="line"><span>                       └── project metadata</span></span>
<span class="line"><span>                            │</span></span>
<span class="line"><span>                            ▼</span></span>
<span class="line"><span>                policy filter → score + risk level → reporter</span></span></code></pre></div><p>The scanner isolates checks from each other: if one throws, its error is written to standard error and the remaining checks still contribute results. Findings use stable IDs so policy and downstream automation can target them safely.</p><h2 id="policy-and-reporting" tabindex="-1">Policy and reporting <a class="header-anchor" href="#policy-and-reporting" aria-label="Permalink to &quot;Policy and reporting&quot;">​</a></h2><p>The scanner returns all findings. Reporters apply the policy by splitting them into active and ignored groups. Only active findings influence the score, risk level, and <code>shouldFail()</code> decision. SARIF intentionally renders the supplied findings directly, while terminal and JSON reporting preserve the active/ignored distinction.</p><h2 id="project-discovery" tabindex="-1">Project discovery <a class="header-anchor" href="#project-discovery" aria-label="Permalink to &quot;Project discovery&quot;">​</a></h2><p>Before checks run, <code>discoverProject()</code> infers:</p><ul><li>package manager from a root lockfile (<code>pnpm</code>, Yarn, Bun, or npm);</li><li>language from TypeScript/JavaScript configuration;</li><li>a recognized framework from <code>package.json</code> dependencies;</li><li>whether the project has Git metadata or Docker configuration.</li></ul><p>That context lets a check choose the correct audit command and lets reporters make the scan intelligible at a glance.</p><h2 id="extending-wreckcheck" tabindex="-1">Extending WreckCheck <a class="header-anchor" href="#extending-wreckcheck" aria-label="Permalink to &quot;Extending WreckCheck&quot;">​</a></h2><p>A check implements the <code>Check</code> interface from <code>@wreckcheck/core</code>: it has an ID, a name, a category, and an async <code>run(context)</code> method that returns findings and duration. Add it to the <code>checks</code> array in <code>@wreckcheck/checks</code> to include it in the standard scan.</p><p>Reporters receive a <code>ScanResult</code> and, where policy-aware, a <code>WreckCheckConfig</code>. This keeps detection logic separate from presentation and makes it straightforward to add another output format.</p><p>For the exported interfaces and functions, see the <a href="/wreckcheck/api/">API reference</a>.</p>`,17)])])}const u=a(s,[["render",r]]);export{k as __pageData,u as default};
